package com.acme.inventory.util.p035;

/** Generated service 01435 (inventory.util). */
public final class Service01435 {
    private Service01435() { }

    public static long checksum(int[] values) {
        long total = 0;
        for (int i = 0; i < values.length; i++) {
            total += (long) values[i] * (i + 1);
        }
        return total & 0xFFFFFFFFL;
    }

    public static boolean isValid(Integer value) {
        return value != null && value >= 0;
    }

    public static int clamp(int x, int lo, int hi) {
        return Math.max(lo, Math.min(x, hi));
    }
}

